shadow_bundle.shadow_css:
:host { display: block; width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }
.wsj-shadow-body { width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }

  :host {
    --paper: #faf8f4;
    --paper-card: #f3efe6;
    --paper-dark: #ebe5d8;
    --ink: #141413;
    --body: #242220;
    --muted: #646059;
    --line: #e4dfd3;
    --line-strong: #c9c2b2;
    --accent: #b85d19;
    --accent-soft: rgba(184, 93, 25, 0.12);
    --crimson: #8f2424;
    --navy-bg: #0f1d2b;
    --navy-card: #16283b;
    --navy-line: #283e56;
    --gold: #d49b4b;
    --font-serif-en: 'Playfair Display', Georgia, serif;
    --font-body-en: 'Lora', Georgia, serif;
    --font-serif-cn: 'Noto Serif SC', 'Songti SC', serif;
    --font-sans: 'Inter', 'Noto Sans SC', -apple-system, sans-serif;
    --font-mono: 'JetBrains Mono', monospace;
  }

  * {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }

  html {
    background-color: var(--paper);
    color: var(--body);
    font-size: 16px;
    -webkit-font-smoothing: antialiased;
    scroll-behavior: smooth;
  }

  .wsj-shadow-body {
    background-color: var(--paper);
    font-family: var(--font-body-en), var(--font-serif-cn);
    line-height: 1.8;
    overflow-x: hidden;
  }

  /* Language Switching Rules */
  :host([lang="zh-CN"]) .lang-en { display: none !important; }
  :host([lang="en"]) .lang-cn { display: none !important; }

  :host([lang="zh-CN"]) .wsj-shadow-body {
    font-family: var(--font-serif-cn);
    line-height: 1.9;
  }
  :host([lang="en"]) .wsj-shadow-body {
    font-family: var(--font-body-en);
    line-height: 1.78;
  }

  /* Reading Progress Bar */
  .progress-track {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 3px;
    background: rgba(20, 20, 19, 0.06);
    z-index: 1000;
  }
  .progress-bar {
    height: 100%;
    width: 0%;
    background: var(--accent);
    transition: width 0.1s ease-out;
  }

  /* Sticky Masthead */
  .masthead {
    position: sticky;
    top: 0;
    z-index: 900;
    background: rgba(250, 248, 244, 0.94);
    backdrop-filter: blur(10px);
    border-bottom: 1px solid var(--line);
    padding: 0.7rem 1.5rem;
  }
  .masthead-inner {
    max-width: 1180px;
    margin: 0 auto;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
  }
  .wsj-brand {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    font-family: var(--font-sans);
  }
  .wsj-logo {
    font-family: var(--font-serif-en);
    font-weight: 800;
    font-size: 1.05rem;
    letter-spacing: 0.08em;
    color: var(--ink);
    text-transform: uppercase;
  }
  .wsj-divider {
    width: 1px;
    height: 14px;
    background: var(--line-strong);
  }
  .wsj-section-tag {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--accent);
    font-weight: 600;
  }

  /* Language Toggle */
  .lang-switch {
    display: inline-flex;
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    border-radius: 999px;
    padding: 2px;
  }
  .lang-btn {
    border: none;
    background: transparent;
    font-family: var(--font-mono);
    font-size: 0.72rem;
    font-weight: 600;
    padding: 0.28rem 0.75rem;
    border-radius: 999px;
    color: var(--muted);
    cursor: pointer;
    transition: all 0.2s ease;
  }
  .lang-btn.active {
    background: var(--ink);
    color: var(--paper);
  }

  /* Hero Header */
  .hero-header {
    max-width: 1180px;
    margin: 0 auto;
    padding: 3.5rem 1.5rem 2.5rem;
    border-bottom: 1px solid var(--ink);
  }
  .hero-kicker-row {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.75rem;
    margin-bottom: 1.25rem;
    font-family: var(--font-mono);
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.09em;
  }
  .kicker-pill {
    background: var(--ink);
    color: var(--paper);
    padding: 0.22rem 0.65rem;
    font-weight: 700;
  }
  .kicker-meta {
    color: var(--accent);
    font-weight: 600;
  }
  .hero-title {
    font-family: var(--font-serif-en), var(--font-serif-cn);
    font-size: clamp(2.1rem, 4.3vw, 3.6rem);
    font-weight: 800;
    line-height: 1.16;
    color: var(--ink);
    letter-spacing: -0.015em;
    margin-bottom: 1.2rem;
    max-width: 960px;
  }
  :host([lang="zh-CN"]) .hero-title {
    font-family: var(--font-serif-cn);
    line-height: 1.25;
    letter-spacing: -0.01em;
  }
  .hero-dek {
    font-size: clamp(1.12rem, 1.8vw, 1.38rem);
    color: var(--muted);
    line-height: 1.55;
    max-width: 820px;
    margin-bottom: 2rem;
    font-weight: 400;
  }

  /* Byline & Dossier Bar */
  .byline-bar {
    display: grid;
    grid-template-columns: 1fr auto;
    gap: 1.5rem;
    padding-top: 1.25rem;
    border-top: 1px solid var(--line);
    font-family: var(--font-sans);
    font-size: 0.85rem;
    color: var(--muted);
    align-items: center;
  }
  .byline-authors strong {
    color: var(--ink);
    font-weight: 600;
  }
  .byline-date {
    font-family: var(--font-mono);
    font-size: 0.76rem;
    color: var(--muted);
    text-transform: uppercase;
    letter-spacing: 0.05em;
  }

  /* Executive Context Dossier Box */
  .dossier-brief {
    max-width: 1180px;
    margin: 2rem auto 0;
    padding: 0 1.5rem;
  }
  .dossier-card {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    border-left: 4px solid var(--accent);
    padding: 1.35rem 1.6rem;
    display: grid;
    grid-template-columns: 190px 1fr;
    gap: 1.5rem;
    align-items: start;
  }
  .dossier-label {
    font-family: var(--font-mono);
    font-size: 0.75rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--accent);
    line-height: 1.4;
  }
  .dossier-label span.sub {
    display: block;
    color: var(--muted);
    font-weight: 400;
    margin-top: 0.25rem;
    font-size: 0.7rem;
  }
  .dossier-text {
    font-family: var(--font-sans);
    font-size: 0.93rem;
    line-height: 1.68;
    color: var(--body);
  }

  /* Main Editorial Grid System */
  .editorial-stage {
    max-width: 1180px;
    margin: 0 auto;
    padding: 3rem 1.5rem 5rem;
  }

  .act-section {
    margin-bottom: 4rem;
    padding-bottom: 3.5rem;
    border-bottom: 1px solid var(--line);
  }
  .act-section:last-of-type {
    border-bottom: none;
    margin-bottom: 1rem;
  }

  .act-header {
    margin-bottom: 2rem;
    display: flex;
    align-items: baseline;
    gap: 1rem;
    border-bottom: 2px solid var(--ink);
    padding-bottom: 0.65rem;
  }
  .act-num {
    font-family: var(--font-mono);
    font-size: 0.78rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--accent);
  }
  .act-title {
    font-family: var(--font-serif-en), var(--font-serif-cn);
    font-size: 1.35rem;
    font-weight: 700;
    color: var(--ink);
  }

  /* Two-Column Asymmetric Forensic Rail */
  .asymmetric-grid {
    display: grid;
    grid-template-columns: minmax(0, 680px) minmax(260px, 380px);
    gap: 3.5rem;
    justify-content: space-between;
    align-items: start;
  }

  .narrative-col {
    min-width: 0;
  }

  .forensic-rail {
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 1.75rem;
    position: sticky;
    top: 4.5rem;
  }

  /* Prose Styling */
  .prose-p {
    font-size: 1.1rem;
    color: var(--body);
    margin-bottom: 1.45rem;
    word-break: break-word;
  }
  :host([lang="zh-CN"]) .prose-p {
    font-size: 1.08rem;
    line-height: 1.92;
    text-align: left;
  }
  :host([lang="en"]) .prose-p {
    font-size: 1.1rem;
    line-height: 1.8;
  }

  /* Lead Paragraph Styling (No CSS ::first-letter on Chinese) */
  .prose-lead {
    font-size: 1.24rem !important;
    font-weight: 600;
    color: var(--ink);
    border-left: 3px solid var(--accent);
    padding-left: 1.15rem;
    margin-bottom: 1.75rem;
    line-height: 1.72 !important;
  }

  /* Inline Highlighting */
  mark.ed-hl {
    background: linear-gradient(120deg, rgba(184, 93, 25, 0.16) 0%, rgba(184, 93, 25, 0.24) 100%);
    color: var(--ink);
    padding: 0.06em 0.28em;
    border-bottom: 1.5px solid var(--accent);
    font-weight: 600;
  }

  /* Forensic Audio Tape Box (Split Sentence Display) */
  .tape-exhibit {
    background: var(--navy-bg);
    color: #f4f1ea;
    padding: 1.5rem 1.75rem;
    margin: 1.8rem 0;
    border-left: 4px solid var(--gold);
    position: relative;
  }
  .tape-exhibit-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    font-family: var(--font-mono);
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--gold);
    margin-bottom: 0.85rem;
    padding-bottom: 0.55rem;
    border-bottom: 1px solid var(--navy-line);
  }
  .tape-wave {
    display: inline-flex;
    align-items: center;
    gap: 3px;
  }
  .tape-wave i {
    display: inline-block;
    width: 2px;
    background: var(--gold);
  }
  .tape-exhibit blockquote {
    font-family: var(--font-serif-en), var(--font-serif-cn);
    font-size: 1.18rem;
    line-height: 1.6;
    color: #ffffff;
    font-weight: 600;
  }

  /* Sidebar Callout Cards */
  .rail-card {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    padding: 1.35rem 1.4rem;
  }
  .rail-card-kicker {
    font-family: var(--font-mono);
    font-size: 0.7rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.09em;
    color: var(--accent);
    margin-bottom: 0.75rem;
    display: flex;
    align-items: center;
    justify-content: space-between;
  }

  /* Derived Pull Quote */
  .pull-quote {
    background: var(--paper-card);
    border-top: 2px solid var(--ink);
    border-bottom: 1px solid var(--line-strong);
    padding: 1.4rem 1.35rem;
  }
  .pull-quote .quote-text {
    font-family: var(--font-serif-en), var(--font-serif-cn);
    font-size: 1.15rem;
    font-weight: 700;
    line-height: 1.55;
    color: var(--ink);
    margin-bottom: 0.75rem;
  }
  .pull-quote .quote-attrib {
    font-family: var(--font-mono);
    font-size: 0.73rem;
    color: var(--muted);
    text-transform: uppercase;
    letter-spacing: 0.05em;
  }

  /* Derived Metric Card */
  .metric-card {
    background: var(--navy-bg);
    color: var(--paper);
    padding: 1.5rem;
    border-top: 4px solid var(--accent);
  }
  .metric-card .metric-val {
    font-family: var(--font-mono);
    font-size: 2.3rem;
    font-weight: 700;
    color: var(--gold);
    line-height: 1.1;
    margin-bottom: 0.45rem;
  }
  .metric-card .metric-lbl {
    font-family: var(--font-sans);
    font-size: 0.85rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: #ffffff;
    margin-bottom: 0.5rem;
  }
  .metric-card .metric-note {
    font-family: var(--font-sans);
    font-size: 0.8rem;
    line-height: 1.55;
    color: #cbd5e1;
  }

  /* Bespoke SVG Container */
  .diagram-panel {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    padding: 1.6rem;
    margin: 2.25rem 0;
  }
  .diagram-header {
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    align-items: baseline;
    gap: 0.5rem;
    margin-bottom: 1rem;
    padding-bottom: 0.75rem;
    border-bottom: 1px solid var(--line-strong);
  }
  .diagram-title {
    font-family: var(--font-sans);
    font-size: 0.95rem;
    font-weight: 700;
    color: var(--ink);
    text-transform: uppercase;
    letter-spacing: 0.04em;
  }
  .diagram-sub {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    color: var(--muted);
  }
  .diagram-caption {
    font-family: var(--font-sans);
    font-size: 0.78rem;
    color: var(--muted);
    margin-top: 0.85rem;
    padding-top: 0.65rem;
    border-top: 1px solid var(--line);
  }

  /* Official Response Dossier Grid (p11-p14) */
  .response-dossier-wrap {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    padding: 1.65rem;
    margin: 2rem 0;
  }
  .response-dossier-title {
    font-family: var(--font-mono);
    font-size: 0.75rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--accent);
    margin-bottom: 1.1rem;
    padding-bottom: 0.55rem;
    border-bottom: 1px solid var(--line-strong);
  }
  .response-item {
    padding: 0.85rem 0;
    border-bottom: 1px dashed var(--line-strong);
  }
  .response-item:last-child {
    border-bottom: none;
    padding-bottom: 0;
  }
  .response-party-tag {
    display: inline-block;
    font-family: var(--font-mono);
    font-size: 0.68rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.07em;
    background: var(--ink);
    color: var(--paper);
    padding: 0.15rem 0.5rem;
    margin-bottom: 0.45rem;
  }
  .response-item .prose-p {
    margin-bottom: 0.4rem;
    font-size: 0.98rem;
  }

  /* Political Fallout Quote Box */
  .verdict-box {
    background: var(--paper-dark);
    border-left: 4px solid var(--crimson);
    padding: 1.35rem 1.6rem;
    margin: 1.5rem 0;
  }
  .verdict-tag {
    font-family: var(--font-mono);
    font-size: 0.7rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--crimson);
    margin-bottom: 0.45rem;
  }
  .verdict-quote {
    font-family: var(--font-serif-en), var(--font-serif-cn);
    font-size: 1.12rem;
    font-weight: 600;
    color: var(--ink);
    line-height: 1.65;
  }

  /* Key Cast Mini-Cards inside Rail */
  .cast-list {
    display: flex;
    flex-direction: column;
    gap: 0.85rem;
  }
  .cast-row {
    border-top: 1px solid var(--line-strong);
    padding-top: 0.7rem;
  }
  .cast-name {
    font-family: var(--font-sans);
    font-size: 0.84rem;
    font-weight: 700;
    color: var(--ink);
  }
  .cast-role {
    font-family: var(--font-mono);
    font-size: 0.7rem;
    color: var(--accent);
    margin-bottom: 0.25rem;
  }
  .cast-desc {
    font-family: var(--font-sans);
    font-size: 0.78rem;
    color: var(--muted);
    line-height: 1.45;
  }

  /* Footer */
  .wsj-footer {
    border-top: 2px solid var(--ink);
    background: var(--paper-card);
    padding: 2.5rem 1.5rem;
    font-family: var(--font-sans);
    font-size: 0.8rem;
    color: var(--muted);
  }
  .wsj-footer-inner {
    max-width: 1180px;
    margin: 0 auto;
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    gap: 1rem;
  }

  /* Responsive Mobile Reflow (390px target) */
  @media (max-width: 920px) {
    .asymmetric-grid {
      grid-template-columns: 1fr;
      gap: 2.25rem;
    }
    .forensic-rail {
      position: static;
    }
    .dossier-card {
      grid-template-columns: 1fr;
      gap: 0.75rem;
    }
    .byline-bar {
      grid-template-columns: 1fr;
      gap: 0.5rem;
    }
  }

  @media (max-width: 480px) {
    .masthead {
      padding: 0.6rem 1rem;
    }
    .hero-header {
      padding: 2.2rem 1rem 1.8rem;
    }
    .dossier-brief {
      padding: 0 1rem;
    }
    .editorial-stage {
      padding: 2rem 1rem 3.5rem;
    }
    .diagram-panel, .response-dossier-wrap, .tape-exhibit {
      padding: 1.15rem;
    }
  }
